  "strings/CNstrings/failScene.json": {
  "gameModle1": [
    "终究只是追逐黎明的黄昏",
    "常忆画中仙，相望阴阳天",
    "伱转身离去，只留给我一个唯美的背影",
    "也许身在远方,心却从未远离",
    "我颠倒世界，也找不到你的倒影"
  ],
  "gameModle2": [
    "百世轮回终梦坠\\n\\n同生死，共玉碎",
    "不要害怕\\n\\n在你我血液干涸之前\\n\\n贯穿这个游戏",
    "真实就在眼前\\n\\n我们终是一体\\n\\n面向真理",
    "这也许就像笼中小鸟\\n\\n不要害怕\\n\\n释放你的灵魂",
    "越过这镜面\\n\\n是虚幻的另一个世界\\n\\n我在那歌唱"
  ],
  "gameModle3": [
    "百世轮回终梦坠\\n\\n同生死，共玉碎",
    "不要害怕\\n\\n在你我血液干涸之前\\n\\n贯穿这个游戏",
    "真实就在眼前\\n\\n我们终是一体\\n\\n面向真理",
    "这也许就像笼中小鸟\\n\\n不要害怕\\n\\n释放你的灵魂",
    "越过这镜面\\n\\n是虚幻的另一个世界\\n\\n我在那歌唱"
  ]
},
  "strings/CNstrings/guide.json": {
  "level_1_9": "当心！当你经过这个陷阱时\\n\\n空间塌陷会吸引周围四个圆一起翻转",
  "level_2_4": "请注意！虚空混乱引起了航道错乱\\n\\n在这个标记出现时\\n\\n您只能从点进入，箭头出来",
  "level_3_1": "小心！这是一个天然虫洞\\n\\n你经过它时，它会和一个与它相通的\\n\\n原点交换位置",
  "level_3_3": "当心！你的经过会引起爆炸\\n\\n它会打翻与你进入方向\\n\\n垂直线上的所有点",
  "level_3_5": "这是一组对称的奇点，它们太过稳定\\n\\n你必须同时经过它们才能造成翻转\\n\\n否则不会翻转",
  "level_2_5": "注意！这是一个伪装的航线起点\\n\\n它会利用魔法干扰你的视线\\n\\n让你无法分辨哪个才是真正的起点\\n\\n请记住，当你的视线中出现两个起点时\\n\\n有且仅有两个起点\\n\\n被隐藏在所有起点和魔法点中"
},
  "strings/CNstrings/helpText.json": {
  "welcome1_1": "欢迎来到同一个世界：两世之约",
  "welcome1_2": "我们先来熟悉下游戏规则吧",
  "level1_1": "任务1：翻转\\n按住月亮，向右滑动",
  "level1_2": "按住月亮，向左滑动",
  "level1_3": "任务2：把所有的圆翻转为黑色",
  "level1_4": "任务3：把所有的圆翻转为白色",
  "level1_5": "任务4：把所有圆变为同一个颜色\\n注意：这次有两个起点",
  "error": "抱歉！这条路线是不可行的",
  "fail1_1": "失败，请再试一次吧",
  "fail1_2": "失败，请再试一次吧",
  "fail1_3": "失败，黑色才是你的目标",
  "fail1_4": "失败，白色才是你的目标",
  "fail1_5": "失败，它们不在同一个世界",
  "pass1_1": "很好！我们再试一次",
  "pass1_2": "很棒！你已经学会了如何翻转",
  "pass1_3": "很棒！你把它们变成了统一的黑色",
  "pass1_4": "很棒！你把它们变成了统一的白色",
  "pass1_5": "很棒！同一个颜色！同一个世界！",
  "end1_3_1": "喔~对你来说，是不是很简单？",
  "end1_3_2": "我们来试一个复杂的吧！",
  "end1_4_1": "你的挑战才刚刚开始......",
  "end1_4_2": "慢慢的...这会越来越难!\\n智商尤为重要！",
  "end1_4_3": "正在为你开启“同一个世界”\\n尽情享受~",
  "welcome2_1": "欢迎来到同一个世界：四维离殇",
  "welcome2_2": "这是一个全新的世界 \\n游戏玩法也在发生变化",
  "level2_1": "看到空心的点了吗？它们已经被感染了\\n我们必须想办法摆脱它们\\n让它们与正常点成相反的颜色试试吧！",
  "level2_2": "翻转，使空心点与正常点的颜色相反\\n最终它们必须是不同的颜色",
  "level2_3": "我们来试个复杂的吧\\n这次有2个起点哦",
  "fail2_1": "oH，No！你没有使两种点的颜色相反",
  "fail2_2": "失败了……我们没能摆脱它们！",
  "fail2_3": "失败：加油！你能做到的",
  "pass2_1": "看到了吗？\\n空心点都消失了！",
  "pass2_2": "很棒！请牢记以下规则：\\n两种点颜色必须完全不一样！",
  "pass2_3": "喔~你已经完全掌握新玩法了……",
  "end2_3_1": "看来没有什么可以阻挡你了……前进吧~",
  "end2_3_2": "你正在进入同一个世界：四维离殇..."
},
